import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { FaSignOutAlt, FaPlus, FaUser } from 'react-icons/fa';
import axios from 'axios';
import AddMealModal from './AddMealModal';
import MealList from './MealList';
import LoadingSpinner from './LoadingSpinner';
import './MealPlanner.css';

const MealPlanner = ({ selectedUser, onLogout }) => {
  const [activeTab, setActiveTab] = useState('personal');
  const [meals, setMeals] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [showAddModal, setShowAddModal] = useState(false);

  useEffect(() => {
    fetchMeals();
  }, [activeTab]);

  const fetchMeals = async () => {
    try {
      setLoading(true);
      const endpoint = activeTab === 'personal' 
        ? `/api/meals/user/${selectedUser.id}`
        : '/api/meals';
      const response = await axios.get(endpoint);
      setMeals(response.data);
      setError(null);
    } catch (err) {
      setError('שגיאה בטעינת הארוחות');
      console.error('Error fetching meals:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleAddMeal = () => {
    setShowAddModal(true);
  };

  const handleCloseModal = () => {
    setShowAddModal(false);
  };

  const handleMealAdded = () => {
    setShowAddModal(false);
    fetchMeals();
  };

  const handleDeleteMeal = async (mealId) => {
    try {
      await axios.delete(`/api/meals/${mealId}?userId=${selectedUser.id}`);
      fetchMeals();
    } catch (err) {
      console.error('Error deleting meal:', err);
    }
  };

  const filteredMeals = activeTab === 'personal' 
    ? meals.filter(meal => meal.user_id === selectedUser.id)
    : meals;

  return (
    <div className="meal-planner">
      <motion.div
        className="header"
        initial={{ opacity: 0, y: -20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6 }}
      >
        <div className="user-info">
          <div 
            className="user-avatar" 
            style={{ backgroundColor: selectedUser.color }}
          >
            <span className="user-initial">{selectedUser.name.charAt(0)}</span>
          </div>
          <div className="user-details">
            <h1 className="welcome-text">שלום, {selectedUser.name}!</h1>
            <p className="subtitle">תכנון ארוחות שבת</p>
          </div>
        </div>
        <button className="logout-button" onClick={onLogout}>
          <FaSignOutAlt />
          <span>התנתק</span>
        </button>
      </motion.div>

      <motion.div
        className="tabs-container"
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6, delay: 0.2 }}
      >
        <div className="tabs">
          <button
            className={`tab ${activeTab === 'personal' ? 'active' : ''}`}
            onClick={() => setActiveTab('personal')}
          >
            <FaUser />
            <span>מה שאני מכין</span>
          </button>
          <button
            className={`tab ${activeTab === 'all' ? 'active' : ''}`}
            onClick={() => setActiveTab('all')}
          >
            <span>מה שכולם מכינים</span>
          </button>
        </div>
      </motion.div>

      <motion.div
        className="content"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ duration: 0.6, delay: 0.4 }}
      >
        <div className="content-header">
          <h2 className="section-title">
            {activeTab === 'personal' ? 'הארוחות שלי' : 'כל הארוחות'}
          </h2>
          {activeTab === 'personal' && (
            <button className="add-meal-button" onClick={handleAddMeal}>
              <FaPlus />
              <span>הוסף ארוחה</span>
            </button>
          )}
        </div>

        {loading ? (
          <div className="loading-container">
            <LoadingSpinner />
          </div>
        ) : error ? (
          <div className="error-message">
            <p>{error}</p>
            <button onClick={fetchMeals} className="retry-button">
              נסה שוב
            </button>
          </div>
        ) : (
          <AnimatePresence mode="wait">
            <motion.div
              key={activeTab}
              initial={{ opacity: 0, x: 20 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: -20 }}
              transition={{ duration: 0.3 }}
            >
              <MealList
                meals={filteredMeals}
                currentUser={selectedUser}
                onDeleteMeal={handleDeleteMeal}
                showDelete={activeTab === 'personal'}
              />
            </motion.div>
          </AnimatePresence>
        )}
      </motion.div>

      {showAddModal && (
        <AddMealModal
          selectedUser={selectedUser}
          onClose={handleCloseModal}
          onMealAdded={handleMealAdded}
          existingMeals={meals}
        />
      )}
    </div>
  );
};

export default MealPlanner;
